/**
 * The texts of the Wilds in Spanish (WorldDefinition.texts.es; i18n.ts in the engine client): for
 * each English text of the content, as the content has it, its translation. The names are the
 * Spanish names of Kandrax (Ironhold: Ferrozar; the reeve: la alguacil; docs/drafts/
 * story-razed-villages.md). A line that the player hears has no adjective that must agree with the
 * player, who can be a man, a woman or neither. A test (texts.test.ts) checks that every text of
 * the content is here, and nothing else.
 */
export const TEXTS_ES: Readonly<Record<string, string>> = {
  "The Wilds": "Las Tierras Salvajes",
  "It's a tree": "Es un árbol",
  "It's a rock": "Es una roca",
  "Old books. The ink has faded.": "Libros viejos. La tinta se ha borrado.",
  "A candle still burns. Someone was here.": "Una vela aún arde. Alguien ha estado aquí.",
  "A narrow bed. The blanket smells of smoke.": "Una cama estrecha. La manta huele a humo.",
  "A heavy chest with iron bands.": "Un cofre pesado con flejes de hierro.",
  "A barrel of sour wine.": "Un barril de vino agrio.",
  "An old crate, nailed shut.": "Una caja vieja, cerrada con clavos.",
  "A lamp. Someone keeps it lit.": "Una farola. Alguien la mantiene encendida.",
  "Clear, cold water. A few coins shine at the bottom.": "Agua clara y fría. Unas monedas brillan en el fondo.",
  "Tall candles in an iron stand.": "Velas altas en un soporte de hierro.",
  "An old signpost.": "Un poste indicador viejo.",
  "Torn from an imp. Corwin, the peddler of Ironhold, buys it, and the cauldron needs one for an antidote.": "Arrancado a un diablillo. Corwin, el buhonero de Ferrozar, lo compra, y el caldero necesita uno para un antídoto.",
  "Torn from a brute. Corwin, the peddler of Ironhold, buys it, and the cauldron needs one for a strong draught.": "Arrancado a un bruto. Corwin, el buhonero de Ferrozar, lo compra, y el caldero necesita uno para un brebaje fuerte.",
  "A stub of old wax. Corwin, the peddler of Ironhold, buys it.": "Un resto de cera vieja. Corwin, el buhonero de Ferrozar, lo compra.",
  "Silver, with a dark red stone. Corwin, the peddler of Ironhold, buys it.": "Plata, con una piedra roja oscura. Corwin, el buhonero de Ferrozar, lo compra.",
  "Old, dented pewter. Corwin, the peddler of Ironhold, buys it.": "Peltre viejo y abollado. Corwin, el buhonero de Ferrozar, la compra.",
  "Bitter leaves from the woods. The cauldron of Ironhold brews them into draughts.": "Hojas amargas del bosque. El caldero de Ferrozar las convierte en brebajes.",
  "Isolde, the apothecary of Ironhold, sells it. The cauldron makes it from two bundles of herbs.": "Isolde, la boticaria de Ferrozar, lo vende. El caldero lo hace con dos manojos de hierbas.",
  "Isolde, the apothecary of Ironhold, sells it. The cauldron makes it from herbs and an imp horn.": "Isolde, la boticaria de Ferrozar, lo vende. El caldero lo hace con hierbas y un cuerno de diablillo.",
  "Isolde, the apothecary of Ironhold, sells it. The cauldron makes it from two bundles of herbs and a brute tusk.": "Isolde, la boticaria de Ferrozar, lo vende. El caldero lo hace con dos manojos de hierbas y un colmillo de bruto.",
  "Boiled leather, stiff and scarred. It turns a claw now and then.": "Cuero hervido, rígido y lleno de marcas. De vez en cuando para una garra.",
  "Scales of steel on leather, like the skin of a fish. It rattles at each step.": "Escamas de acero sobre cuero, como la piel de un pez. Tintinea a cada paso.",
  "Thousands of small steel rings. Heavy on the shoulders, and loud.": "Miles de anillas de acero. Pesa en los hombros, y suena.",
  "Strips of steel on leather. It stops nearly every blow, and it is very heavy.": "Tiras de acero sobre cuero. Para casi cualquier golpe, y pesa mucho.",
  "Oak boards in an iron rim. Old dents on its face.": "Tablas de roble en un aro de hierro. Abolladuras viejas en la cara.",
  "A long, straight blade. With both hands on the grip, it hits harder.": "Una hoja larga y recta. Con las dos manos en la empuñadura, golpea más fuerte.",
  "A short, quick blade for close work.": "Una hoja corta y rápida para la lucha cuerpo a cuerpo.",
  "A thin blade for the thrust, with a swept guard.": "Una hoja fina para la estocada, con una guarda de lazo.",
  "A heavy head on a long haft. Slow to swing, terrible when it lands.": "Una cabeza pesada en un mango largo. Lenta de mover, terrible cuando acierta.",
  "A head of flanged iron on a short haft.": "Una cabeza de hierro con aletas en un mango corto.",
  "A tall bow of yew. The string sings.": "Un arco alto de tejo. La cuerda canta.",
  "A staff with a blue stone at its top. A mage casts through it.": "Un bastón con una piedra azul en la punta. Un mago lanza sus conjuros con él.",
  "A crooked staff, still green at the top. A druid casts through it.": "Un bastón torcido, aún verde en la punta. Un druida lanza sus conjuros con él.",
  "A charm of bone with a drop of amber. They say that it brings luck.": "Un amuleto de hueso con una gota de ámbar. Dicen que trae suerte.",
  "Leather set with rivets of iron. Light, and a little harder to cut.": "Cuero con remaches de hierro. Ligero, y algo más difícil de cortar.",
  "Shaped plates of steel from head to foot. The best armour in the land, and the heaviest.": "Placas de acero forjadas de la cabeza a los pies. La mejor armadura de estas tierras, y la más pesada.",
  "An old blade that never dulls. A faint blue light runs along its edge.": "Una hoja vieja que nunca pierde el filo. Una luz azul tenue recorre el borde.",
  "A grey cloak that is never wet. Blows slide off it.": "Una capa gris que nunca se moja. Los golpes resbalan en ella.",
  "A plain band with a blue stone. The air round it is a little cold.": "Un aro sencillo con una piedra azul. El aire a su alrededor está algo frío.",
  "Two cuffs of dark leather and silver. They turn blows from bare arms.": "Dos puños de cuero oscuro y plata. Desvían los golpes de los brazos desnudos.",
  "Heavy gloves of iron and hide. In them, your grip could crush a stone.": "Guantes pesados de hierro y piel. Con ellos, tu mano podría aplastar una piedra.",
  "A thin band of silver with a clear gem. Thoughts come quick and sharp.": "Una cinta fina de plata con una gema clara. Las ideas llegan rápidas y claras.",
  "A red stone on a chain. Its warmth goes into the blood.": "Una piedra roja en una cadena. Su calor entra en la sangre.",
  "A broad belt with a buckle of a bearded face. It makes you hardy.": "Un cinturón ancho con una hebilla en forma de cara barbuda. Te hace más resistente.",
  "Soft boots of grey leather. Your steps make no sound in them.": "Botas blandas de cuero gris. Con ellas tus pasos no hacen ruido.",
  "A heavy blade on a long pole. It keeps a claw at a distance.": "Una hoja pesada en un asta larga. Mantiene las garras a distancia.",
  "Marta, the innkeeper": "Marta, la posadera",
  "Welcome to the Crooked Lantern! Sit down before you fall down.": "¡Esto es el Farol Torcido! Siéntate antes de que te caigas.",
  "What do you have to drink?": "¿Qué tienes de beber?",
  "Do you have a room?": "¿Tienes una habitación?",
  "Any news?": "¿Alguna noticia?",
  "Not now.": "Ahora no.",
  "Ale, cheap and brown. Cider, cheap and yellow. And something green that the apothecary makes.": "Cerveza, barata y oscura. Sidra, barata y amarilla. Y una cosa verde que hace la boticaria.",
  "The ale, then.": "Una cerveza, entonces.",
  "What is the green one?": "¿Qué es la verde?",
  "Nothing for me.": "Nada para mí.",
  "Here. Do not tell me what you think of it. Everybody tells me.": "Toma. No me digas qué te parece. Todo el mundo me lo dice.",
  "Thank you.": "Gracias.",
  "An ale costs coin. Come back when the woods have paid you.": "La cerveza cuesta monedas. Vuelve cuando el bosque te haya pagado.",
  "I will.": "Volveré.",
  "Nobody knows. It warms you, and then it remembers you. I stopped asking.": "Nadie lo sabe. Te calienta, y luego se acuerda de ti. Ya no pregunto.",
  "You know what is in it.": "Tú sabes lo que lleva.",
  "Goodbye.": "Adiós.",
  "Ashroot, and a pinch from the green jar. Isolde told me once. I wish she had not.": "Raíz de ceniza y una pizca del tarro verde. Isolde me lo dijo una vez. Ojalá no lo hubiera hecho.",
  "The beds are taken. Folk from the farms sleep here now. The farms are too close to the trees.": "Las camas están ocupadas. Ahora duerme aquí gente de las granjas. Las granjas están demasiado cerca de los árboles.",
  "Surely there is a corner for a friendly face?": "¿Seguro que hay un rincón para una cara amable?",
  "Ha! For that smile... The bed by the east wall is yours when you need it. If the woods knock you down, wake up here, not out there.": "¡Ja! Por esa sonrisa... La cama junto a la pared este es tuya cuando la necesites. Si el bosque te tumba, despierta aquí, no ahí fuera.",
  "Thank you, Marta.": "Gracias, Marta.",
  "The minstrel knows only sad songs, the reeve writes letters that nobody answers, and the smith works all night.": "El juglar solo sabe canciones tristes, la alguacil escribe cartas que nadie contesta y el herrero trabaja toda la noche.",
  "Why all night?": "¿Por qué toda la noche?",
  "Ask him. He says the woods grow thicker every year. More blades, fewer nails.": "Pregúntale a él. Dice que el bosque crece más espeso cada año. Más espadas, menos clavos.",
  "Another round?": "¿Otra ronda?",
  "Wipe your boots. The woods come in on them.": "Límpiate las botas. El bosque entra pegado a ellas.",
  "The fire is free. The ale is not.": "El fuego es gratis. La cerveza no.",
  "{name}! Sit, sit. The fire is warm.": "¡{name}! Siéntate, siéntate. El fuego calienta.",
  "A song for a traveller? I only know sad ones.": "¿Una canción para quien viene de lejos? Solo sé canciones tristes.",
  "This one is about a miller who walked into the woods and came back wrong.": "Esta va de un molinero que entró en el bosque y volvió cambiado.",
  "...Perhaps another night.": "...Quizá otra noche.",
  "La la... no. Again.": "La la... no. Otra vez.",
  "Who has a rhyme for 'imp'?": "¿Quién tiene una rima para «diablillo»?",
  "One more song, then bed.": "Una canción más, y a la cama.",
  "Ah, {name}! I will put you in a song.": "¡Ah, {name}! Te pondré en una canción.",
  "The smith": "El herrero",
  "Mind the forge. It bites. I sell iron, and I buy it back when you do not need it.": "Cuidado con la fragua. Muerde. Vendo hierro, y te lo compro cuando ya no lo necesitas.",
  "Show me armour.": "Enséñame armaduras.",
  "Show me weapons.": "Enséñame armas.",
  "I have gear to sell.": "Tengo equipo para vender.",
  "Leather for the quick, steel for the stubborn.": "Cuero para los rápidos, acero para los tozudos.",
  "Leather armour.": "Armadura de cuero.",
  "Studded leather.": "Cuero tachonado.",
  "Scale mail.": "Cota de escamas.",
  "Something heavier.": "Algo más pesado.",
  "Heavy iron. It stops a tusk, and it slows the feet that carry it.": "Hierro pesado. Para un colmillo, y frena los pies que lo llevan.",
  "Chain mail.": "Cota de malla.",
  "Splint armour.": "Armadura de bandas.",
  "Plate armour.": "Armadura de placas.",
  "And a shield?": "¿Y un escudo?",
  "Oak, and a rim of iron. It turns more blows than you think.": "Roble, y un aro de hierro. Para más golpes de los que crees.",
  "A shield.": "Un escudo.",
  "Something else.": "Otra cosa.",
  "Every blade in Ironhold has been through my hands twice. These are new.": "Todas las hojas de Ferrozar han pasado dos veces por mis manos. Estas son nuevas.",
  "A longsword.": "Una espada larga.",
  "A shortsword.": "Una espada corta.",
  "A rapier.": "Un estoque.",
  "An axe for the strong, a glaive to keep the claws away, a mace for the plain.": "Un hacha para los fuertes, una guja para tener lejos las garras, una maza para quien no se complica.",
  "A greataxe.": "Un hacha a dos manos.",
  "A glaive.": "Una guja.",
  "A mace.": "Una maza.",
  "And a bow?": "¿Y un arco?",
  "A traveller left a longbow for its price. Yew, and a good string.": "Un viajero dejó un arco largo a cambio de su precio. Tejo, y buena cuerda.",
  "The longbow.": "El arco largo.",
  "I pay half of what I ask. Iron is iron. What is it?": "Pago la mitad de lo que pido. El hierro es hierro. ¿Qué es?",
  "Armour or a shield.": "Una armadura o un escudo.",
  "A weapon or a staff.": "Un arma o un bastón.",
  "Put it on the bench. Light or heavy?": "Déjalo en el banco. ¿Ligera o pesada?",
  "Heavy, then. Let me see the rings and the rivets.": "Pesada, entonces. Déjame ver las anillas y los remaches.",
  "A shield. Dented, I suppose.": "Un escudo. Abollado, supongo.",
  "Nothing now.": "Nada por ahora.",
  "A blade? Let me see the edge.": "¿Una hoja? Déjame ver el filo.",
  "Heavier work. Let me feel the weight.": "Trabajo pesado. Déjame sentir el peso.",
  "A bow or a staff.": "Un arco o un bastón.",
  "Wood. I burn it in the forge, but I pay for it.": "Madera. La quemo en la fragua, pero la pago.",
  "A longbow.": "Un arco largo.",
  "An arcane staff.": "Un bastón arcano.",
  "A druid staff.": "Un bastón druídico.",
  "Wear it well. Come back when it breaks.": "Úsalo bien. Vuelve cuando se rompa.",
  "Coin first, and room in your pack for it.": "Primero las monedas, y sitio en tu mochila.",
  "Iron is iron. Here is your coin.": "El hierro es hierro. Aquí tienes tus monedas.",
  "That is all.": "Eso es todo.",
  "I see none in your pack. If you wear it, take it off first.": "No veo ninguno en tu mochila. Si lo llevas puesto, quítatelo primero.",
  "Hot iron waits for nobody.": "El hierro caliente no espera a nadie.",
  "More blades. Always more blades.": "Más espadas. Siempre más espadas.",
  "Where are my tongs?": "¿Dónde están mis tenazas?",
  "{name}. Good to see you whole.": "{name}. Me alegra verte de una pieza.",
  "Peace to you, traveller.": "La paz sea contigo, caminante.",
  "The candles of this chapel have burned for a hundred years.": "Las velas de esta capilla llevan cien años ardiendo.",
  "When the night is long, come in and sit for a while.": "Cuando la noche sea larga, entra y siéntate un rato.",
  "Peace on this house.": "Paz a esta casa.",
  "The light holds.": "La luz resiste.",
  "Pray, and keep to the road.": "Reza, y no te salgas del camino.",
  "Peace, {name}.": "Paz, {name}.",
  "Isolde, the apothecary": "Isolde, la boticaria",
  "Careful with that shelf. Half of it heals and half of it kills.": "Cuidado con esa estantería. La mitad cura y la otra mitad mata.",
  "Which half is which?": "¿Qué mitad es cuál?",
  "Do you sell remedies?": "¿Vendes remedios?",
  "Do you have something for wounds?": "¿Tienes algo para las heridas?",
  "I will not touch anything.": "No tocaré nada.",
  "The labels say. Unless they fell off. Some of them fell off.": "Lo dicen las etiquetas. Salvo que se hayan caído. Algunas se cayeron.",
  "What do you know of the imps?": "¿Qué sabes de los diablillos?",
  "Then I need a friend who knows the labels. A friend's price, perhaps?": "Entonces necesito una amiga experta. ¿Un precio de amiga, quizá?",
  "Draughts for wounds, for poison, and for worse. Coin first.": "Brebajes para las heridas, para el veneno y para cosas peores. Primero las monedas.",
  "A healing draught.": "Un brebaje curativo.",
  "An antidote.": "Un antídoto.",
  "A strong draught.": "Un brebaje fuerte.",
  "Ha. You talk like a peddler. For you, a friend's price.": "Ja. Hablas como un buhonero. Para ti, precio de amiga.",
  "Drink it before you need it, not after.": "Bébelo antes de necesitarlo, no después.",
  "Coin first, and room in your pack for the bottle.": "Primero las monedas, y sitio en tu mochila para el frasco.",
  "Ashroot, for cuts. Salt, for a scratch from an imp. Wash it, and then wash it again.": "Raíz de ceniza, para los cortes. Sal, para el arañazo de un diablillo. Lávalo, y luego lávalo otra vez.",
  "Why salt?": "¿Por qué sal?",
  "Could I brew a remedy myself?": "¿Podría preparar yo un remedio?",
  "You do not grow your ashroot here. Where do you find it?": "La raíz de ceniza no la cultivas aquí. ¿Dónde la encuentras?",
  "You have a good eye. It grows wild, low between the trees. Most people walk over it and never see it.": "Tienes buen ojo. Crece silvestre, baja, entre los árboles. Casi todos la pisan y nunca la ven.",
  "You have the head for it. Use my cauldron, if you bring your own herbs. Two bundles make a draught for wounds.": "Tienes cabeza para esto. Usa mi caldero, si traes tus propias hierbas. Dos manojos hacen un brebaje para las heridas.",
  "And for poison?": "¿Y para el veneno?",
  "Herbs, and the horn of an imp: what bites you also cures you. The strong draught needs a brute's tusk. Do not ask how I know.": "Hierbas, y el cuerno de un diablillo: lo que te muerde también te cura. El brebaje fuerte necesita el colmillo de un bruto. No preguntes cómo lo sé.",
  "Their claws are dirty. And the old women say that the woods do not like salt. Both can be true.": "Sus garras están sucias. Y las viejas dicen que al bosque no le gusta la sal. Las dos cosas pueden ser ciertas.",
  "They come out of the dark under the trees, and they hate the light. I cut one open once. It was mostly smoke.": "Salen de la oscuridad bajo los árboles, y odian la luz. Una vez abrí uno. Casi todo era humo.",
  "Mostly smoke?": "¿Casi todo humo?",
  "Smoke, and teeth. I keep the teeth in the green jar. Do not touch the green jar.": "Humo, y dientes. Guardo los dientes en el tarro verde. No toques el tarro verde.",
  "I will not.": "No lo tocaré.",
  "Salt, salt and more salt.": "Sal, sal y más sal.",
  "Who took my ashroot?": "¿Quién se ha llevado mi raíz de ceniza?",
  "Do not touch the green jar.": "No toques el tarro verde.",
  "{name}. Still in one piece, I see.": "{name}. Sigues de una pieza, por lo que veo.",
  "Elama Rothenel, the reeve": "Elama Rothenel, la alguacil",
  "I am the reeve of Ironhold. Of what is left of it.": "Soy la alguacil de Ferrozar. De lo que queda de él.",
  "What happened to the town?": "¿Qué le pasó al pueblo?",
  "Who lived in the shut houses?": "¿Quién vivía en las casas cerradas?",
  "What is that map?": "¿Qué es ese mapa?",
  "The woods came closer, the roads went bad, and four houses shut this year. The families went south.": "El bosque se acercó, los caminos se volvieron peligrosos y este año cerraron cuatro casas. Las familias se fueron al sur.",
  "Will they come back?": "¿Volverán?",
  "I write to them every week. Nobody has written back. Yet.": "Les escribo cada semana. Nadie ha contestado. Todavía.",
  "The chandler, an old couple, a family I hardly knew. And the granary... the granary is another matter.": "El velero, una pareja de ancianos, una familia que apenas conocía. Y el granero... el granero es otra cosa.",
  "What about the granary?": "¿Y el granero?",
  "You miss the old couple.": "Echas de menos a los ancianos.",
  "I do. They never trusted my strongbox. They buried their savings across the lane from their door, a few steps to the west.": "Sí. Nunca se fiaron de mi caja fuerte. Enterraron sus ahorros al otro lado del callejón, frente a su puerta, unos pasos al oeste.",
  "Nobody dug it up?": "¿Nadie lo ha desenterrado?",
  "Not I. It is theirs, if they come back. If you find it... I did not tell you.": "Yo no. Es suyo, si vuelven. Si lo encuentras... yo no te he dicho nada.",
  "It is barred from the inside. We do not know who barred it. We do not open it.": "Está atrancado por dentro. No sabemos quién lo atrancó. No lo abrimos.",
  "Why not?": "¿Por qué no?",
  "Your ledgers say that grain went in all summer, and none came out.": "Tus libros dicen que entró grano todo el verano y no salió nada.",
  "...You read my ledgers. Then you know why I do not open it. Something in there eats.": "...Has leído mis libros. Entonces sabes por qué no lo abro. Algo ahí dentro come.",
  "Because I am the reeve, and I say so. ...And because something in there scratches at night.": "Porque soy la alguacil, y lo digo yo. ...Y porque algo ahí dentro araña de noche.",
  "You can tell me. I keep secrets.": "Puedes contármelo. Sé guardar secretos.",
  "...The last reeve went into the granary with a lamp. The lamp came back out. He did not.": "...El alguacil de antes entró en el granero con un farol. El farol volvió a salir. Él no.",
  "The valley. The woods are inked black, and every year I ink a little more of it.": "El valle. El bosque está entintado de negro, y cada año entinto un poco más.",
  "The marks in the black: are they the boarded houses?": "Las marcas en lo negro: ¿son las casas tapiadas?",
  "You read a map well. Yes. The families boarded their doors and left their strongboxes inside. Strong arms could open them. I did not say that.": "Sabes leer un mapa. Sí. Las familias tapiaron sus puertas y dejaron dentro sus cofres. Unos brazos fuertes podrían abrirlos. Yo no he dicho eso.",
  "Taxes, taxes...": "Impuestos, impuestos...",
  "Another letter with no answer.": "Otra carta sin respuesta.",
  "The gate, the lamps. Always the lamps.": "La puerta, las farolas. Siempre las farolas.",
  "Good evening, {name}.": "Buenas noches, {name}.",
  "Brann, the watchman": "Brann, el guardia",
  "Halt! Who walks the road at night?": "¡Alto! ¿Quién anda por el camino de noche?",
  "A traveller, from the hut in the woods.": "Alguien de paso, de la cabaña del bosque.",
  "Who are you?": "¿Quién eres?",
  "What is this place?": "¿Qué lugar es este?",
  "Nobody. Goodbye.": "Nadie. Adiós.",
  "The hut by the old signpost? Then you walked the road alone. Brave, or a fool.": "¿La cabaña del poste viejo? Entonces has venido sin compañía por el camino. Eso es valor, o locura.",
  "What is out there in the woods?": "¿Qué hay ahí fuera, en el bosque?",
  "Can I come in?": "¿Puedo entrar?",
  "Brann, of the town watch. The whole watch, these days. The others went south.": "Brann, de la guardia del pueblo. Toda la guardia, estos días. Los demás se fueron al sur.",
  "Why did they leave?": "¿Por qué se fueron?",
  "Ironhold. An inn, a forge, a chapel, and more empty houses every year.": "Ferrozar. Una posada, una fragua, una capilla y más casas vacías cada año.",
  "Where should I go first?": "¿Adónde voy primero?",
  "Imps, quick as cats. And the big grey ones with clubs. They never come past the lamps.": "Diablillos, rápidos como gatos. Y los grandes grises con garrotes. Nunca pasan de las farolas.",
  "I will be careful.": "Tendré cuidado.",
  "The priest says it is the chapel candles. I say: do not ask. Just keep them lit.": "El sacerdote dice que son las velas de la capilla. Yo digo: no preguntes. Tú mantenlas encendidas.",
  "You do not believe the priest.": "No crees al sacerdote.",
  "No. One winter the candles went out for a week, and the imps still stayed away. Something else keeps them out.": "No. Un invierno las velas se apagaron una semana, y los diablillos siguieron lejos. Algo más los mantiene fuera.",
  "The gate is open to anyone who is not an imp. Welcome to Ironhold.": "La puerta está abierta para cualquiera que no sea un diablillo. Te doy la bienvenida a Ferrozar.",
  "You look like a man who needs a drink. The next one is on me.": "Tienes cara de necesitar un trago. El próximo lo pago yo.",
  "Ha! A traveller with manners. Then hear this: the grey brutes are slow. Walk away from them. Never run blind into the dark.": "¡Ja! Alguien de fuera con modales. Entonces escucha: los brutos grises son lentos. Aléjate de ellos. Nunca corras a ciegas hacia la oscuridad.",
  "The roads went bad, the trade stopped, and the families followed the trade. Some of us stayed.": "Los caminos se volvieron peligrosos, el comercio se paró y las familias se fueron con el comercio. Algunos nos quedamos.",
  "Why did you stay?": "¿Por qué te quedaste?",
  "Somebody has to light the lamps.": "Alguien tiene que encender las farolas.",
  "The Crooked Lantern, for a fire and a drink. The apothecary, if the woods have marked you.": "El Farol Torcido, para un fuego y un trago. La botica, si el bosque te ha dejado marca.",
  "Nothing comes past this gate.": "Nada pasa de esta puerta.",
  "Keep to the lamps.": "No te alejes de las farolas.",
  "A quiet night. Too quiet.": "Una noche tranquila. Demasiado tranquila.",
  "Evening, {name}. Keep to the lamps.": "Buenas noches, {name}. No te alejes de las farolas.",
  "Corwin, the peddler": "Corwin, el buhonero",
  "Pots! Pins! Candles! Well... I had candles. I buy what the woods give you.": "¡Ollas! ¡Alfileres! ¡Velas! Bueno... tenía velas. Compro lo que te da el bosque.",
  "What do you buy?": "¿Qué compras?",
  "Do you buy trophies?": "¿Compras trofeos?",
  "Why do you not sell candles?": "¿Por qué no vendes velas?",
  "Rings, cups, candle stubs. Things that people leave behind when they go south.": "Anillos, copas, cabos de vela. Cosas que la gente deja atrás cuando se va al sur.",
  "A silver ring.": "Un anillo de plata.",
  "A pewter cup.": "Una copa de peltre.",
  "A candle stub.": "Un cabo de vela.",
  "Horns, tusks and furs. The apothecary pays me for the horns and the tusks; the furs go south. Everybody wins.": "Cuernos, colmillos y pieles. La boticaria me paga los cuernos y los colmillos; las pieles van al sur. Todos ganamos.",
  "An imp horn.": "Un cuerno de diablillo.",
  "A brute tusk.": "Un colmillo de bruto.",
  "The chandler shut his shop when the roads went bad. Now I sell what I can find, and I find nothing.": "El velero cerró su tienda cuando los caminos se volvieron peligrosos. Ahora vendo lo que encuentro, y no encuentro nada.",
  "A fair price. Fairer than most. What else?": "Un precio justo. Más justo que la mayoría. ¿Qué más?",
  "You do not have one. I do not buy promises.": "No tienes ninguno. No compro promesas.",
  "Pots and pins!": "¡Ollas y alfileres!",
  "Fine pins, nearly new!": "¡Alfileres finos, casi nuevos!",
  "Who needs a pot? Anybody?": "¿Quién necesita una olla? ¿Alguien?",
  "{name}! My best customer!": "¡{name}! ¡Mi mejor cliente!",
  "The fountain was dry for three summers.": "La fuente estuvo seca tres veranos.",
  "Then one night it filled again. Nobody knows why.": "Luego, una noche, se llenó otra vez. Nadie sabe por qué.",
  "I come here to listen to it. It sounds like rain.": "Vengo a escucharla. Suena como la lluvia.",
  "Listen... like rain.": "Escucha... como la lluvia.",
  "Three summers dry.": "Tres veranos seca.",
  "My husband built that wall.": "Mi marido levantó ese muro.",
  "Hello, {name}. Listen... like rain.": "Hola, {name}. Escucha... como la lluvia.",
  "Are you an adventurer? Have you seen the imps?": "¿Vas de aventuras? ¿Has visto a los diablillos?",
  "Mother says they cannot come past the lamps.": "Madre dice que no pueden pasar de las farolas.",
  "I am not scared. Much.": "No tengo miedo. Mucho.",
  "Catch me if you can!": "¡A que no me pillas!",
  "I saw an imp! I think.": "¡He visto un diablillo! Creo.",
  "Not scared, not scared!": "¡No tengo miedo, no tengo miedo!",
  "{name}! Did you see an imp?": "¡{name}! ¿Has visto un diablillo?",
  "The Crooked Lantern": "El Farol Torcido",
  "Ale. It smells better than it tastes.": "Cerveza. Huele mejor de lo que sabe.",
  "Turnips, and one very old onion.": "Nabos, y una cebolla muy vieja.",
  "Bottles of cider, of ale, and of something green.": "Botellas de sidra, de cerveza y de algo verde.",
  "A sticky table. Someone has cut a crow into it.": "Una mesa pegajosa. Alguien ha grabado un cuervo en ella.",
  "A narrow bed by the east wall. It is not mine.": "Una cama estrecha junto a la pared este. No es mía.",
  "A game of dice, left half played.": "Una partida de dados a medias.",
  "Smithy": "Herrería",
  "The forge is hot. The coals breathe.": "La fragua está caliente. Las brasas respiran.",
  "Dents on dents. The smith hits hard.": "Abolladuras sobre abolladuras. El herrero golpea fuerte.",
  "Water for the hot iron.": "Agua para el hierro caliente.",
  "Nails, horseshoes and broken blades.": "Clavos, herraduras y hojas rotas.",
  "Chapel": "Capilla",
  "The candles never go out. Someone sees to that.": "Las velas nunca se apagan. Alguien se encarga de ello.",
  "An old book of prayers, open at the prayer for travellers.": "Un viejo libro de oraciones, abierto por la oración de los viajeros.",
  "In the margin, in small letters: \"Who sleeps once under this roof wakes under it.\" The chapel keeps the lost.": "En el margen, en letra pequeña: «Quien duerme una vez bajo este techo despierta bajo él». La capilla guarda a los perdidos.",
  "Chandler": "Velería",
  "Boarded up. A note on the door says: CLOSED. GONE SOUTH.": "Tapiada. Una nota en la puerta dice: CERRADO. NOS FUIMOS AL SUR.",
  "Apothecary": "Botica",
  "Jars of roots, of powders, and of dried things with legs.": "Tarros de raíces, de polvos y de cosas secas con patas.",
  "Labels in an old hand: \"Two bundles of herbs, boiled, close a wound.\" \"With the horn of an imp, they draw out its poison.\"": "Etiquetas con letra antigua: «Dos manojos de hierbas, hervidos, cierran una herida». «Con el cuerno de un diablillo, sacan su veneno».",
  "The cauldron": "El caldero",
  "The cauldron bubbles. Isolde lets you use it, if you bring your own herbs.": "El caldero borbotea. Isolde te deja usarlo, si traes tus propias hierbas.",
  "Brew a healing draught (2 bundles of herbs).": "Preparar un brebaje curativo (2 manojos de hierbas).",
  "Brew an antidote (herbs and an imp horn).": "Preparar un antídoto (hierbas y un cuerno de diablillo).",
  "Brew a strong draught (2 herbs and a brute tusk).": "Preparar un brebaje fuerte (2 hierbas y un colmillo de bruto).",
  "Leave it.": "Dejarlo.",
  "The brew turns clear. You fill a small bottle and put it in your pack.": "El brebaje se aclara. Llenas un frasquito y lo guardas en la mochila.",
  "Brew another.": "Preparar otro.",
  "You do not have what the brew needs, or your pack has no room for the bottle.": "No tienes lo que necesita el brebaje, o tu mochila no tiene sitio para el frasco.",
  "Look again.": "Mirar otra vez.",
  "Cloudy glass. You see only your own face.": "Cristal turbio. Solo ves tu propia cara.",
  "Small brass scales, for very small doses.": "Una balanza pequeña de latón, para dosis muy pequeñas.",
  "Locked. Nobody answers.": "Cerrado con llave. Nadie contesta.",
  "Reeve": "Alguacil",
  "Ledgers of taxes, of births and of deaths. More deaths, lately.": "Libros de impuestos, de nacimientos y de muertes. Más muertes, últimamente.",
  "The numbers do not add up. The granary took in grain all summer, and no cart took any out.": "Las cuentas no cuadran. El granero recibió grano todo el verano, y ningún carro sacó nada.",
  "A map of the valley. The woods round the town are inked black.": "Un mapa del valle. El bosque alrededor del pueblo está entintado de negro.",
  "Small marks in the black: an X by each house in the woods that its family boarded up.": "Pequeñas marcas en lo negro: una X junto a cada casa del bosque que su familia tapió.",
  "The town's strongbox. Locked, and nearly empty.": "La caja fuerte del pueblo. Cerrada con llave, y casi vacía.",
  "Letters to the families who left. None of them is sent.": "Cartas a las familias que se fueron. Ninguna se ha enviado.",
  "Granary": "Granero",
  "The doors are barred from the inside.": "Las puertas están atrancadas por dentro.",
  "Locked. Through a crack you see an empty room, and thick dust.": "Cerrado con llave. Por una rendija ves una sala vacía y mucho polvo.",
  "A book of the old roads of the valley.": "Un libro de los viejos caminos del valle.",
  "\"In the west, a chapel where the lost are found again. Sleep once under its roof, and it remembers you.\"": "«En el oeste, una capilla donde los perdidos vuelven a encontrarse. Duerme una vez bajo su techo, y te recordará».",
  "The accounts of a household. Candles, salt, rope.": "Las cuentas de una casa. Velas, sal, cuerda.",
  "The last page: \"We boarded the door and left the box inside. We will come back for it.\" Nobody came back.": "La última página: «Tapiamos la puerta y dejamos la caja dentro. Volveremos a por ella». Nadie volvió.",
  "A book of tales for children, with the pictures cut out.": "Un libro de cuentos para niños, con los dibujos recortados.",
  "In the margin, in a child's hand: \"The imps hate the light. Keep to the lamps.\"": "En el margen, con letra de niño: «Los diablillos odian la luz. No te alejes de las farolas».",
  "A herbal, with pressed leaves between the pages.": "Un herbario, con hojas prensadas entre las páginas.",
  "\"Two bundles of herbs, boiled with care, close a wound. With the horn of an imp, they draw out its poison.\"": "«Dos manojos de hierbas, hervidos con cuidado, cierran una herida. Con el cuerno de un diablillo, sacan su veneno».",
  "A bestiary. The pages are swollen with damp.": "Un bestiario. Las páginas están hinchadas de humedad.",
  "Of the grey brute: \"It raises its club slowly. Strike while it is up, and strike hard.\"": "Del bruto gris: «Levanta su garrote despacio. Golpea mientras lo tiene en alto, y golpea fuerte».",
  "Your bed. The straw is fresh.": "Tu cama. La paja es nueva.",
  "Your chest. Nothing in it yet.": "Tu cofre. Aún no hay nada dentro.",
  "Your few books. You know them by heart.": "Tus pocos libros. Te los sabes de memoria.",
  "Water from the stream. Cold, and good.": "Agua del arroyo. Fría, y buena.",
  "NOTICE. The gate shuts at dusk. Keep to the lamps. By order of the Reeve.": "AVISO. La puerta se cierra al anochecer. No te alejes de las farolas. Por orden de la Alguacil.",
  "Under it, in another hand: LOST, one grey goat. Answers to nothing.": "Debajo, con otra letra: PERDIDA, una cabra gris. No atiende a ningún nombre.",
  "A third notice, half torn off: the names of the families who boarded up their houses in the woods. \"Goods left inside at the owner's risk.\"": "Un tercer aviso, medio arrancado: los nombres de las familias que tapiaron sus casas en el bosque. «Los bienes dejados dentro quedan a riesgo del dueño».",
  "It reads: IRONHOLD. The arrow points west, down the road.": "Pone: FERROZAR. La flecha señala al oeste, camino abajo.",
  "Under it, cut with a knife: KEEP TO THE ROAD.": "Debajo, grabado a cuchillo: NO TE SALGAS DEL CAMINO.",
  "Home": "Hogar",
  "Ironhold": "Ferrozar",
  // Story phase 2 (2026-10-11): the letter, the reeve, the merchant and the cart, the smith's lever, the quests.
  "A merchant's cart, loaded with crates and a sack.": "El carro de un comerciante, cargado con cajas y un saco.",
  "A bar of dark iron from the smith of Ironhold. The merchant on the road needs it for the cart.": "Una barra de hierro oscuro del herrero de Ferrozar. El comerciante del camino la necesita para el carro.",
  "Mind the forge. It bites. You look like somebody who needs iron.": "Cuidado con la fragua. Muerde. Tienes cara de necesitar hierro.",
  "A merchant on the road needs a lever for a broken cart.": "Un comerciante del camino necesita una palanca para un carro roto.",
  "A cart in the mud, on that road? Take this lever. Tell the merchant that my forge sells nails too.": "¿Un carro en el barro, en ese camino? Toma esta palanca. Dile al comerciante que mi fragua también vende clavos.",
  "I am the reeve of Ironhold. Of what is left of it. You look like somebody with business here.": "Soy la alguacil de Ferrozar. De lo que queda de él. Pareces alguien con asuntos aquí.",
  "Thrain Steelforge sent me. Who burns the homesteads?": "Me envía Thrain Forjacero. ¿Quién quema los caseríos?",
  "No business. What happened to the town?": "Ningún asunto. ¿Qué le pasó al pueblo?",
  "Steelforge sent you? Good. Three homesteads burned since the spring. Nobody saw who burned them.": "¿Te envía Forjacero? Bien. Tres caseríos han ardido desde la primavera. Nadie vio quién los quemó.",
  "What else do you know?": "¿Qué más sabes?",
  "You fear that it is more than bandits.": "Temes que sea algo más que bandidos.",
  "Every house was searched before the fire. The chests, the floors, even the hearths. Whoever it is, they look for something.": "Registraron cada casa antes del fuego. Los arcones, los suelos, hasta las chimeneas. Sean quienes sean, buscan algo.",
  "I will find out who.": "Averiguaré quién ha sido.",
  "Bandits take the coins and run. These leave the coins, and take the time to burn. That is not hunger.": "Los bandidos cogen las monedas y huyen. Estos dejan las monedas y se toman su tiempo para quemar. Eso no es hambre.",
  "The merchant": "El comerciante",
  "Careful, the mud is deep here. The wheel came off, and I cannot lift the cart and put the wheel on at once.": "Cuidado, aquí el barro es hondo. Se salió la rueda, y no puedo levantar el carro y ponerla a la vez.",
  "Can I help?": "¿Puedo ayudar?",
  "Where are you going?": "¿Adónde vas?",
  "To Ironhold, to see if this road can carry a trade. Silverspring needs tools, and Ironhold has a forge.": "A Ferrozar, a ver si este camino aguanta un comercio. Silverspring necesita herramientas, y Ferrozar tiene una fragua.",
  "Can I help with the cart?": "¿Puedo ayudar con el carro?",
  "Somebody must lift the cart while I put the wheel on. Or bring me a lever: the smith of Ironhold has iron to spare.": "Alguien tiene que levantar el carro mientras pongo la rueda. O tráeme una palanca: al herrero de Ferrozar le sobra hierro.",
  "Stand back. I will lift it.": "Apártate. Yo lo levanto.",
  "I will ask the smith for a lever.": "Le pediré una palanca al herrero.",
  "Back again? The wheel is still in the mud.": "¿Otra vez por aquí? La rueda sigue en el barro.",
  "Here: a lever from the smith.": "Toma: una palanca del herrero.",
  "Not yet.": "Todavía no.",
  "Hold it... there! The wheel is on. Take these coins. You saved me a day in the mud.": "Aguanta... ¡ya está! La rueda está puesta. Toma estas monedas. Me has ahorrado un día en el barro.",
  "What news do you bring?": "¿Qué noticias traes?",
  "A good lever! Now it is easy... There. The wheel is on. Take these coins. You saved me a day in the mud.": "¡Buena palanca! Ahora es fácil... Ya está. La rueda está puesta. Toma estas monedas. Me has ahorrado un día en el barro.",
  "The wheel holds, thanks to you. I rest a little, then I go on to Ironhold.": "La rueda aguanta, gracias a ti. Descanso un poco y sigo hacia Ferrozar.",
  "Silverspring digs mithril, but it needs tools and blades. Ironhold has a forge, and it looks at that mithril with hungry eyes.": "Silverspring saca mithril, pero necesita herramientas y hojas. Ferrozar tiene una fragua, y mira ese mithril con los dientes largos.",
  "The Sovereignty and the Enclave both claim these woods.": "La Soberanía y el Enclave reclaman estos bosques.",
  "A trader hears more than that. Tell me the rest.": "Un comerciante oye más que eso. Cuéntame el resto.",
  "You know your history. The Iron Sovereignty and the Mithril Enclave both want the Wilds, and neither of them plays fair.": "Conoces tu historia. La Soberanía del Hierro y el Enclave del Mithril quieren las Tierras Salvajes, y ninguno juega limpio.",
  "Between us: the Sovereignty and the Enclave fight for these woods with dirty tricks. Be careful who pays you.": "Aquí entre tú y yo: la Soberanía y el Enclave se pelean estos bosques con malas artes. Cuidado con quién te paga.",
  "A long road, and a bad one.": "Un camino largo, y malo.",
  "Ironhold, then Silverspring. Then home.": "Ferrozar, luego Silverspring. Luego, a casa.",
  "Who walks there? A friend, I hope.": "¿Quién anda ahí? Gente de paz, espero.",
  "Your table. A letter lies by the candle, sealed with a hammer and an anvil.": "Tu mesa. Junto a la vela hay una carta, sellada con un martillo y un yunque.",
  "It is from Thrain Steelforge: \"Homesteads burn in the Wilds, one after another, and nobody knows who burns them. Find out for me.\"": "Es de Thrain Forjacero: «En las Tierras Salvajes arden caseríos, uno tras otro, y nadie sabe quién los quema. Averígualo por mí».",
  "\"Begin in Ironhold, west down the road. The reeve there, Elama Rothenel, wrote to me first. Thrain.\"": "«Empieza en Ferrozar, camino abajo hacia el oeste. La alguacil, Elama Rothenel, fue la primera en escribirme. Thrain».",
  "The Razed Villages": "Pueblos Arrasados",
  "Thrain Steelforge asks me to find out who burns the homesteads of the Wilds. His letter says: begin with Elama Rothenel, the reeve of Ironhold.": "Thrain Forjacero me pide que averigüe quién quema los caseríos de las Tierras Salvajes. Su carta dice: empieza por Elama Rothenel, la alguacil de Ferrozar.",
  "Elama Rothenel, the reeve of Ironhold, says that three homesteads burned since the spring. Nobody saw who burned them. Each house was searched before the fire.": "Elama Rothenel, la alguacil de Ferrozar, dice que tres caseríos han ardido desde la primavera. Nadie vio quién los quemó. Registraron cada casa antes del fuego.",
  "I know now who burns the homesteads of the Wilds.": "Ya sé quién quema los caseríos de las Tierras Salvajes.",
  "The Broken Cart": "El carro roto",
  "A merchant's cart broke down on the road to Ironhold. Somebody must lift it while the merchant puts the wheel on, or bring a lever from the smith of Ironhold.": "El carro de un comerciante se ha roto en el camino a Ferrozar. Alguien tiene que levantarlo mientras el comerciante pone la rueda, o traer una palanca del herrero de Ferrozar.",
  "The smith of Ironhold gave me a lever for the merchant's cart on the road.": "El herrero de Ferrozar me dio una palanca para el carro del comerciante del camino.",
  "I helped the merchant to put the wheel back on the cart. The merchant paid me, and goes on to Ironhold.": "Ayudé al comerciante a poner la rueda del carro. Me pagó, y sigue hacia Ferrozar.",
  // Story phase 3a (2026-10-11): the argument in the house of the reeve, the raid, the soldier and the villager.
  "You heard it. Hobgoblins in the hills, on the way to Silverspring. Somebody must warn them, and the soldiers will not go.": "Ya lo has oído. Hobgoblins en las colinas, de camino a Silverspring. Alguien tiene que avisarles, y los soldados no irán.",
  "I will warn Silverspring.": "Avisaré a Silverspring.",
  "Why will the soldiers not go?": "¿Por qué no irán los soldados?",
  "They are soldiers of the Sovereignty, not of Ironhold. They say that they guard the town. I say that they guard the Sovereignty.": "Son soldados de la Soberanía, no de Ferrozar. Dicen que guardan el pueblo. Yo digo que guardan a la Soberanía.",
  "Thank you. Ironhold cannot pay you, I am sorry. Silverspring is north-east of here, over the hills. Do not fight the hobgoblins: they are many.": "Gracias. Ferrozar no puede pagarte, lo siento. Silverspring está al noreste, tras las colinas. No te enfrentes a los hobgoblins: son muchos.",
  "Who are Himo and Brys?": "¿Quiénes son Himo y Brys?",
  "Our scouts. They watch the hills for us. Brys came back alone last night. Himo... we do not know.": "Nuestros exploradores. Vigilan las colinas por nosotros. Brys volvió sola anoche. De Himo... no sabemos nada.",
  "Silverspring is north-east of here, over the hills. Go, and be careful.": "Silverspring está al noreste, tras las colinas. Ve, y ten cuidado.",
  "Tell me about the town.": "Háblame del pueblo.",
  "My brother farms by the hills. I have not heard from him for a week.": "Mi hermano tiene una granja junto a las colinas. Hace una semana que no sé nada de él.",
  "The reeve says to wait. I am tired of waiting.": "La alguacil dice que esperemos. Estoy harto de esperar.",
  "Hobgoblins. In our hills.": "Hobgoblins. En nuestras colinas.",
  "Somebody must do something.": "Alguien tiene que hacer algo.",
  "Wait, wait, always wait.": "Esperar, esperar, siempre esperar.",
  "{name}! Any news from the hills?": "¡{name}! ¿Noticias de las colinas?",
  "A soldier of the Sovereignty": "Un soldado de la Soberanía",
  "Move along, traveller. The reeve's house is no place to stand about.": "Circula. La casa de la alguacil no es sitio para quedarse mirando.",
  "Who do you serve?": "¿A quién sirves?",
  "What is happening in the hills?": "¿Qué pasa en las colinas?",
  "Nothing that the Sovereignty cannot handle. Move along.": "Nada que la Soberanía no pueda manejar. Circula.",
  "The Iron Sovereignty. Ironhold is ours to guard. Ironhold, and nothing else.": "A la Soberanía del Hierro. Guardamos Ferrozar. Ferrozar, y nada más.",
  "I know that look. Stay out of this, traveller. The hills are no place for heroes.": "Conozco esa mirada. No te metas en esto. Las colinas no son lugar para valientes.",
  "Silverspring needs help.": "Silverspring necesita ayuda.",
  "You want the hobgoblins to reach Silverspring.": "Quieres que los hobgoblins lleguen a Silverspring.",
  "Silverspring has the Enclave. Let the Enclave help it.": "Silverspring tiene al Enclave. Que la ayude el Enclave.",
  "...Careful. A traveller who meddles in the business of the Sovereignty can have an accident in those hills.": "...Cuidado. Quien se mete en los asuntos de la Soberanía puede tener un accidente en esas colinas.",
  "Move along.": "Circula.",
  "The Sovereignty keeps this town safe.": "La Soberanía mantiene este pueblo a salvo.",
  "Hills, hills. Always the hills.": "Colinas, colinas. Siempre las colinas.",
  "{name}. Keep out of trouble.": "{name}. No te metas en líos.",
  "...and they go straight for Silverspring. Brys says that there were two squads of them.": "...y se dirigen directos a Silverspring. Brys dice que eran un par de pelotones.",
  "And Himo?": "¿Y Himo?",
  "They took him. Brys thinks that he is still alive.": "Lo capturaron. Brys cree que sigue vivo.",
  "We must warn Silverspring!": "¡Tenemos que avisar a Silverspring!",
  "And leave Ironhold with no defence? One messenger alone dies in those hills.": "¿Y dejar Ferrozar indefensa? Un mensajero solo muere en esas colinas.",
  "Then send soldiers with the messenger!": "¡Pues mandad soldados con el mensajero!",
  "My soldiers stay here. That is my last word.": "Mis soldados se quedan aquí. Es mi última palabra.",
  "Let the hobgoblins have Silverspring. It saves the Sovereignty the work.": "Que los hobgoblins se queden Silverspring. Así la Soberanía se ahorra el trabajo.",
  "Enough! ...You, by the door. Come here. I need a word with you.": "¡Basta! ...Tú, junto a la puerta. Ven aquí. Necesito hablar contigo.",
  "The Hobgoblin Raid": "Incursión Hobgoblin",
  "In the house of the reeve of Ironhold, I heard that hobgoblins go through the hills to Silverspring. They took the scout Himo. The reeve wants a word with me.": "En la casa de la alguacil de Ferrozar oí que unos hobgoblins van por las colinas hacia Silverspring. Capturaron al explorador Himo. La alguacil quiere hablar conmigo.",
  "Elama Rothenel asks me to warn Silverspring, north-east of Ironhold, before the hobgoblins come. Ironhold cannot pay. The soldiers of the Sovereignty want me to stay out of it.": "Elama Rothenel me pide que avise a Silverspring, al noreste de Ferrozar, antes de que lleguen los hobgoblins. Ferrozar no puede pagar. Los soldados de la Soberanía quieren que no me meta.",
  "Silverspring gave me a title in its guard, and a bed in the town.": "Silverspring me dio un título en su guardia, y una cama en el pueblo.",
  // Story phase 3c (2026-10-11): the loot of the scouts.
  "A thick grey fur from the packs of the hobgoblin scouts. Corwin, the peddler of Ironhold, buys it.": "Una piel gris y espesa de las mochilas de los exploradores hobgoblin. Corwin, el buhonero de Ferrozar, la compra.",
  "A badger fur.": "Una piel de tejón.",
  // Story phase 4a (2026-10-11): Silverspring, its people and Kasmut Parnika.
  "Kasmut Parnika, of the Enclave": "Kasmut Parnika, del Enclave",
  "Kasmut Parnika, veteran of the Mithril Enclave. I train the militia of Silverspring. What do you want?": "Kasmut Parnika, veterana del Enclave del Mithril. Entreno a la milicia de Silverspring. ¿Qué quieres?",
  "Tell me about Silverspring.": "Háblame de Silverspring.",
  "A militia? Of whom?": "¿Una milicia? ¿De quién?",
  "Why is a veteran of the Enclave out here?": "¿Qué hace aquí una veterana del Enclave?",
  "The spring brings mithril down from the hills, a pinch at a time. The people pan it from the stream, and the jeweller makes rings of it. Small work. Honest work.": "El manantial baja mithril de las colinas, pizca a pizca. La gente lo criba en el arroyo, y la joyera hace anillos con él. Trabajo pequeño. Trabajo honrado.",
  "Mithril? Then the town must be rich.": "¿Mithril? Entonces el pueblo será rico.",
  "Who wants the mithril?": "¿Quién quiere el mithril?",
  "Rich? A pinch a day feeds a family. The rich live in the capital, and they never pan anything.": "¿Rico? Una pizca al día da de comer a una familia. Los ricos viven en la capital, y nunca criban nada.",
  "You do not like the rich.": "No te gustan los ricos.",
  "I served them for thirty years. I know what they are. Here, at least, the people who work also eat.": "Los serví durante treinta años. Sé lo que son. Aquí, al menos, quien trabaja también come.",
  "Everybody. The Enclave buys it, and the Iron Sovereignty wants the stream. Ironhold has iron and tools, and we have mithril. We should trade. Instead we watch each other.": "Todo el mundo. El Enclave lo compra, y la Soberanía del Hierro quiere el arroyo. Ferrozar tiene hierro y herramientas; nosotros, mithril. Deberíamos comerciar. Y nos vigilamos.",
  "Panners and miners with spears. Brave people, and badly trained. I do what I can. The Enclave sends advice, not soldiers.": "Cribadores y mineros con lanzas. Gente valiente, y mal entrenada. Hago lo que puedo. El Enclave manda consejos, no soldados.",
  "The Enclave sent me. That is all.": "Me envió el Enclave. Nada más.",
  "That is not all.": "Eso no es todo.",
  "The priests say that the gods watch the spring.": "Los sacerdotes dicen que los dioses velan por el manantial.",
  "...No, it is not. I left the capital because I kept a secret, and powerful people wanted it. I keep it still. Ask me again, and we are done.": "...No, no lo es. Dejé la capital porque guardé un secreto, y gente poderosa lo quería. Aún lo guardo. Pregúntame otra vez, y hemos terminado.",
  "The priests say many things. The gods watch the spring, and I watch the hills. Guess which of us sees the hobgoblins first.": "Los sacerdotes dicen muchas cosas. Los dioses vigilan el manantial, y yo vigilo las colinas. Adivina quién ve antes a los hobgoblins.",
  "You came up the north road? Few do now. What is it?": "¿Has subido por el camino del norte? Ya casi nadie lo hace. ¿Qué pasa?",
  "Hobgoblins come through the hills to Silverspring.": "Unos hobgoblins vienen por las colinas hacia Silverspring.",
  "Hobgoblins? Who says so? Ironhold? Ironhold sends us a warning, and keeps its soldiers at home. Of course it does.": "¿Hobgoblins? ¿Quién lo dice? ¿Ferrozar? Ferrozar nos manda un aviso, y deja a sus soldados en casa. Cómo no.",
  "Ironhold has no soldiers. The soldiers are of the Sovereignty.": "Ferrozar no tiene soldados. Los soldados son de la Soberanía.",
  "Their scouts waited in the grove on the road. I killed them.": "Sus exploradores esperaban en la arboleda del camino. Los maté.",
  "...You are right. I am sorry. You walked that road to tell us, and nobody paid you for it. I will ready the militia. Thank you.": "...Tienes razón. Lo siento. Has recorrido ese camino para avisarnos, y nadie te ha pagado por ello. Prepararé a la milicia. Gracias.",
  "Then their war band is close behind. I will ready the militia and close the town. If you meet that band on the road... Silverspring will not forget it.": "Entonces su partida de guerra viene detrás. Prepararé a la milicia y cerraré el pueblo. Si te encuentras esa partida en el camino... Silverspring no lo olvidará.",
  "Spears up! ...They are not even here.": "¡Lanzas arriba! ...Si ni siquiera están aquí.",
  "Thirty years of this.": "Treinta años con esto.",
  "Watch the hills. Always the hills.": "Vigilad las colinas. Siempre las colinas.",
  "{name}. Keep your weapon clean.": "{name}. Mantén limpia tu arma.",
  "Tova, of the Silver Trout": "Tova, de la Trucha de Plata",
  "Welcome to the Silver Trout! Shut the door, the wind off the stream is cold.": "¡Te doy la bienvenida a la Trucha de Plata! Cierra la puerta, el viento del arroyo es frío.",
  "Cider from the valley, and ale from Ironhold. The last barrel of it: the carts from Ironhold do not come now.": "Sidra del valle, y cerveza de Ferrozar. El último barril: los carros de Ferrozar ya no vienen.",
  "An ale, then.": "Una cerveza, entonces.",
  "There. Drink it slowly. When it is gone, it is gone.": "Toma. Bébela despacio. Cuando se acabe, se acabó.",
  "An ale costs coin, friend. The stream does not pay me either.": "Una cerveza cuesta monedas. A mí el arroyo tampoco me paga.",
  "I understand.": "Lo entiendo.",
  "The rooms are for the guard of the town these days, and for its friends. Kasmut decides who is a friend.": "Estos días las habitaciones son para la guardia del pueblo y para quien tenga su amistad. Eso lo decide Kasmut.",
  "Kasmut drills the militia every dawn. The panners grumble, and then they go. Something in the hills worries her.": "Kasmut entrena a la milicia cada amanecer. Los cribadores refunfuñan, y luego van. Algo en las colinas la preocupa.",
  "Shut the door!": "¡Cierra la puerta!",
  "Cider, cider, nobody wants the cider.": "Sidra, sidra, nadie quiere la sidra.",
  "The last barrel. The very last.": "El último barril. El último de verdad.",
  "{name}! Come in out of the wind.": "¡{name}! Pasa, que hace viento.",
  "Rings of mithril, light as a breath. The Enclave buys nearly all of them.": "Anillos de mithril, ligeros como un suspiro. El Enclave compra casi todos.",
  "Mithril takes a spell as wool takes a dye. I sing to it while it cools. Do not laugh.": "El mithril toma un hechizo como la lana toma un tinte. Le canto mientras se enfría. No te rías.",
  "I sell only to the Enclave, or to a friend of the town. Kasmut decides who that is.": "Solo vendo al Enclave, o a quien tenga la amistad del pueblo. Eso lo decide Kasmut.",
  "Light as a breath...": "Ligero como un suspiro...",
  "Steady hands, steady hands.": "Pulso firme, pulso firme.",
  "Where are the small tongs?": "¿Dónde están las tenacillas?",
  "{name}. Mind the dust: it is worth more than you.": "{name}. Cuidado con el polvo: vale más que tú.",
  "Doran, of the militia": "Doran, de la milicia",
  "Halt! ...Oh. A traveller. We do not see many from the west.": "¡Alto! ...Ah. Alguien de viaje. Del oeste no viene mucha gente.",
  "Silverspring. The spring rises at the north end of the town, and the stream carries mithril dust past every door.": "Silverspring. El manantial nace en el extremo norte del pueblo, y el arroyo lleva polvo de mithril por delante de cada puerta.",
  "Who is in charge here?": "¿Quién manda aquí?",
  "Doran, of the militia. A panner, most days. Kasmut gives me a spear at dawn and takes it back at dusk.": "Doran, de la milicia. Cribador, casi siempre. Kasmut me da una lanza al amanecer y me la quita al anochecer.",
  "Kasmut Parnika, in the militia hall by the gate. A veteran of the Enclave. She shouts, but she is fair.": "Kasmut Parnika, en el cuartel de la milicia, junto a la entrada. Una veterana del Enclave. Grita, pero es justa.",
  "Halt! ...Oh, it is you.": "¡Alto! ...Ah, eres tú.",
  "My arms ache.": "Me duelen los brazos.",
  "Spear up, spear down. Spear up...": "Lanza arriba, lanza abajo. Lanza arriba...",
  "{name}! Welcome back to Silverspring.": "¡{name}! Otra vez en Silverspring.",
  "See the glitter in the water? Mithril dust. A whole day of panning for a pinch.": "¿Ves el brillo en el agua? Polvo de mithril. Un día entero cribando por una pizca.",
  "The spring rises at the north end of the town. Nobody knows how deep it goes.": "El manantial nace en el extremo norte del pueblo. Nadie sabe lo hondo que es.",
  "The Sovereignty wants this stream. Over my bones.": "La Soberanía quiere este arroyo. Por encima de mi cadáver.",
  "A pinch, a pinch...": "Una pizca, una pizca...",
  "Cold water, cold hands.": "Agua fría, manos frías.",
  "There! ...No. Sand.": "¡Ahí! ...No. Arena.",
  "Mind your boots in the stream, {name}.": "Cuidado con las botas en el arroyo, {name}.",
  "Militia": "Milicia",
  "Spears, and more spears. Some of them are pick handles with a blade tied on.": "Lanzas, y más lanzas. Algunas son mangos de pico con una hoja atada.",
  "A map of the hills between Silverspring and Ironhold. Pins mark where the panners saw tracks.": "Un mapa de las colinas entre Silverspring y Ferrozar. Unos alfileres marcan dónde vieron huellas los cribadores.",
  "The pins make a line. Whatever made the tracks comes from the south-west, straight at Silverspring.": "Los alfileres forman una línea. Lo que dejó esas huellas viene del suroeste, directo hacia Silverspring.",
  "The pay chest of the militia. A note inside says: 'Owed: everything.'": "El cofre de la paga de la milicia. Dentro, una nota dice: 'Se debe: todo.'",
  "Water, and a ladle. Kasmut drills them hard.": "Agua, y un cazo. Kasmut los entrena duro.",
  "Letters to the Enclave that ask for soldiers. The answers ask for patience.": "Cartas al Enclave que piden soldados. Las respuestas piden paciencia.",
  "The Silver Trout": "La Trucha de Plata",
  "Cider from the valley, and stream water to cut it.": "Sidra del valle, y agua del arroyo para rebajarla.",
  "Bottles of cider, and a jar of pickled trout.": "Botellas de sidra, y un tarro de trucha en escabeche.",
  "A clean bed under a quilt of blue wool. It is not mine.": "Una cama limpia bajo una colcha de lana azul. No es mía.",
  "A scrubbed table. Someone has carved a trout into its edge.": "Una mesa bien fregada. Alguien ha tallado una trucha en el borde.",
  "A game of stones. The panners play it for pinches of dust.": "Un juego de piedras. Los cribadores se juegan pizcas de polvo.",
  "Jeweller": "Joyería",
  "A ball of clear glass. In its middle, a thread of silver light turns slowly.": "Una bola de cristal claro. En su centro gira despacio un hilo de luz plateada.",
  "Work of the Enclave: a spell of finding, closed in glass. It glows when mithril is near.": "Obra del Enclave: un hechizo de búsqueda, encerrado en cristal. Brilla cuando hay mithril cerca.",
  "A small anvil, polished like a mirror.": "Un yunque pequeño, pulido como un espejo.",
  "Scales for dust. The weights are no bigger than seeds.": "Una balanza para el polvo. Las pesas no son más grandes que semillas.",
  "Locked. Behind the shutters, somebody holds their breath.": "Cerrado. Tras los postigos, alguien contiene la respiración.",
  "Locked. A voice inside says: 'Come back when the hills are quiet.'": "Cerrado. Una voz dentro dice: 'Vuelve cuando las colinas estén tranquilas.'",
  "Barred. A pan, a sieve and a pick lean against the door.": "Atrancado. Una batea, un cedazo y un pico se apoyan en la puerta.",
  "Locked. A dog barks inside, then stops.": "Cerrado. Un perro ladra dentro, y luego calla.",
  "NOTICE. Every able hand to the militia hall at dawn. By order of K. Parnika.": "AVISO. Toda persona capaz, al cuartel de la milicia al amanecer. Por orden de K. Parnika.",
  "Under it: FOUND, one silver ring with a trout on it. Ask at the inn.": "Debajo: ENCONTRADO, un anillo de plata con una trucha. Preguntad en la posada.",
  "A newer notice: the Enclave raises the price that it pays for mithril dust. Under it, in chalk: \"And the price of bread?\"": "Un aviso más nuevo: el Enclave sube lo que paga por el polvo de mithril. Debajo, en tiza: \"¿Y el precio del pan?\"",
  "Silverspring": "Silverspring",
  // Story phase 4b to 4d (2026-10-11): the war band, its camp, Himo, the raid and its rewards.
  "A thick post, driven deep into the ground.": "Un poste grueso, clavado hondo en la tierra.",
  "A fire in a ring of stones.": "Un fuego en un círculo de piedras.",
  "A nugget of mithril from the stream of Silverspring, light as a feather. The smith of Ironhold buys it.": "Una pepita de mithril del arroyo de Silverspring, ligera como una pluma. El herrero de Ferrozar la compra.",
  "The permit of Silverspring, sealed by Kasmut Parnika: the jeweller of Silverspring sells mithril at cost to its holder.": "El permiso de Silverspring, sellado por Kasmut Parnika: la joyera de Silverspring vende mithril a precio de coste a quien lo tiene.",
  "Is that mithril in your pack? From Silverspring? I pay you ten coins a nugget, and I ask no questions.": "¿Eso es mithril, en tu mochila? ¿De Silverspring? Te pago diez monedas por pepita, y no hago preguntas.",
  "One nugget, then.": "Una pepita, entonces.",
  "Light as a feather, and harder than my anvil. Bring me more.": "Ligero como una pluma, y más duro que mi yunque. Tráeme más.",
  "Another one.": "Otra.",
  "Himo is home! His mother has not slept for a week. Ironhold owes you more than it can pay.": "¡Himo está en casa! Su madre lleva una semana sin dormir. Ferrozar te debe más de lo que puede pagar.",
  "His family paid me.": "Su familia me ha pagado.",
  "Good people. Now go to Silverspring, and tell them that the war band is dead. They will want to hear it from you.": "Buena gente. Ahora ve a Silverspring, y diles que la partida de guerra ha muerto. Querrán oírlo de tu boca.",
  "Himo... fell? So close to home? ...I will tell his mother myself. It is my work.": "Himo... ¿ha caído? ¿Tan cerca de casa? ...Se lo diré yo a su madre. Es mi trabajo.",
  "I am sorry.": "Lo siento.",
  "You again. The war band... dead on the road? Before it came near us?": "Otra vez tú. ¿La partida de guerra... muerta en el camino? ¿Antes de acercarse siquiera?",
  "Dead, all of it. Its camp is empty.": "Muerta, entera. Su campamento está vacío.",
  "Then Silverspring owes you its life. From today you are of the guard of Silverspring. Tova keeps a bed for you at the Silver Trout. And take this permit: the jeweller sells you mithril at cost.": "Entonces Silverspring te debe la vida. Desde hoy eres de la guardia de Silverspring. Tova te guarda una cama en la Trucha de Plata. Y toma este permiso: la joyera te vende mithril a precio de coste.",
  "Thank you, Kasmut.": "Gracias, Kasmut.",
  "You fought in our streets beside my militia. The town stands because of you.": "Luchaste en nuestras calles junto a mi milicia. El pueblo sigue en pie gracias a ti.",
  "It was our fight.": "Era nuestra lucha.",
  "From today you are of the guard of Silverspring. Tova keeps a bed for you at the Silver Trout. And speak well of our mithril, wherever you go.": "Desde hoy eres de la guardia de Silverspring. Tova te guarda una cama en la Trucha de Plata. Y habla bien de nuestro mithril allá donde vayas.",
  "A guard of Silverspring. Ha. It suits you. The hills are quiet, for now.": "De la guardia de Silverspring. Ja. Te sienta bien. Las colinas están tranquilas, por ahora.",
  "The war band is dead? Then their prisoner, the scout of Ironhold... Find him, if he lives, and take him home. Then come back to me.": "¿La partida de guerra ha muerto? Entonces su prisionero, el explorador de Ferrozar... Encuéntralo, si vive, y llévalo a casa. Luego vuelve a verme.",
  "Kasmut made me one of the guard.": "Kasmut me ha hecho de la guardia.",
  "So she did! Then the bed under the blue quilt is yours. If the hills knock you down, wake up here, not out there.": "¡Así que lo hizo! Entonces la cama de la colcha azul es tuya. Si las colinas te tumban, despierta aquí, no ahí fuera.",
  "Thank you, Tova.": "Gracias, Tova.",
  "Ilsa, the jeweller": "Ilsa, la joyera",
  "How do you work it?": "¿Cómo lo trabajas?",
  "Will you sell me mithril?": "¿Me vendes mithril?",
  "Here is the permit of Silverspring.": "Aquí tienes el permiso de Silverspring.",
  "The permit of Kasmut! Then you pay what the Enclave pays: five coins a nugget.": "¡El permiso de Kasmut! Entonces pagas lo que paga el Enclave: cinco monedas por pepita.",
  "Here. When you sell it, tell them where it comes from.": "Toma. Cuando la vendas, di de dónde viene.",
  "Five coins, friend, and room in your pack. Mithril is not given away.": "Cinco monedas, y sitio en la mochila. El mithril no se regala.",
  "A tent of the war band. It stinks of wet fur and smoke.": "Una tienda de la partida de guerra. Apesta a pelo mojado y a humo.",
  "Empty, but for bones and a broken spear.": "Vacía, salvo unos huesos y una lanza rota.",
  "The fire of the war band. Bones in the ashes.": "El fuego de la partida de guerra. Huesos entre las cenizas.",
  "Stolen crates, empty now.": "Cajas robadas, ya vacías.",
  "A thick post, driven deep into the ground. Cut ropes lie at its foot.": "Un poste grueso, clavado hondo en la tierra. A sus pies hay cuerdas cortadas.",
  "A barrel of bad water.": "Un barril de agua podrida.",
  "Himo, the scout of Ironhold, is tied to the post. Bruised, and alive.": "Himo, el explorador de Ferrozar, está atado al poste. Magullado, y vivo.",
  "You cut the ropes. \"Get me home,\" he says. \"Please.\"": "Cortas las cuerdas. \"Llévame a casa\", dice. \"Por favor.\"",
  "I killed the scouts of the hobgoblins in the grove. Their war band marches on Silverspring along the north road. If I catch it on the road, Himo may still live.": "Maté a los exploradores de los hobgoblins en la arboleda. Su partida de guerra marcha hacia Silverspring por el camino del norte. Si la alcanzo en el camino, puede que Himo aún viva.",
  "The war band fell on the north road. Its camp is in the hills off the road, and Himo may be a prisoner there.": "La partida de guerra cayó en el camino del norte. Su campamento está en las colinas, fuera del camino, y puede que Himo esté allí prisionero.",
  "Himo is free. I must take Himo home to Ironhold, through the woods.": "Himo está libre. Tengo que llevar a Himo a casa, a Ferrozar, a través del bosque.",
  "Himo is home in Ironhold, and his family paid me. Silverspring must hear that the war band is dead.": "Himo está en casa, en Ferrozar, y su familia me ha pagado. Silverspring tiene que saber que la partida de guerra ha muerto.",
  "Himo fell on the way home. The war band is dead all the same: Silverspring must hear of it.": "Himo cayó de camino a casa. La partida de guerra ha muerto de todos modos: Silverspring tiene que saberlo.",
  "The war band came to Silverspring before me. The hobgoblins attack the town!": "La partida de guerra llegó a Silverspring antes que yo. ¡Los hobgoblins atacan el pueblo!",
  "The war band fell in the streets of Silverspring. Himo died in its camp, the panners say. Kasmut wants to see me.": "La partida de guerra cayó en las calles de Silverspring. Himo murió en su campamento, dicen los cribadores. Kasmut quiere verme.",
};
